function compute(inputs){
  var Q=inputs.Q,K=inputs.K,V=inputs.V,d=Q[0].length,s=inputs.scale?Math.sqrt(d):1;
  var S=Q.map(function(q){return K.map(function(k){var t=0;for(var i=0;i<d;i++)t+=q[i]*k[i];return t/s;});});
  var W=S.map(function(r){var m=Math.max.apply(null,r);var e=r.map(function(x){return Math.exp(x-m);});var z=e.reduce(function(a,b){return a+b;},0);return e.map(function(x){return x/z;});});
  var O=W.map(function(w){return V[0].map(function(_,j){var t=0;for(var i=0;i<V.length;i++)t+=w[i]*V[i][j];return t;});});
  var rs=W.map(function(w){return w.reduce(function(a,b){return a+b;},0);});
  var mx=Math.max.apply(null,W[0]);
  return {S:S,W:W,O:O,rowsum:rs,w00:W[0][0],insight:'Query 1 puts '+(100*mx).toFixed(0)+'% of its attention on its best-matching key.'};
}
